function refreshDetail(){if($('detail-dialog').open){$('detail-dialog').close();detail(current)}}function assign(id,pid){const s=state.services.find(x=>x.id===id);if(!s||finished(s)||s.partner)throw Error('Este serviço não está disponível para despacho.');const p=eligible(s).find(x=>x.id===pid);if(!p)throw Error('Parceiro indisponível ou modalidade incompatível.');s.partner=pid;s.status='Aceita';s.events.push('Parceiro atribuído pela central: '+p.name);log(id+' atribuído a '+p.name);save();refreshDetail();toast('Parceiro atribuído na demonstração.');return {id,status:s.status,partner:p.name}}
function advance(id){const s=state.services.find(x=>x.id===id);if(!s||!s.partner||finished(s))return;const idx=paths[s.type].indexOf(s.status);if(idx<0||idx>=paths[s.type].length-1)return;s.status=paths[s.type][idx+1];s.events.push('Central atualizou para '+s.status);log(id+': '+s.status);save();refreshDetail();toast('Status atualizado.')}function cancel(id){const s=state.services.find(x=>x.id===id);if(!s||finished(s))return;s.status='Cancelada';s.events.push('Cancelamento realizado pela central');log(id+' cancelado pela central');save();refreshDetail();toast('Solicitação cancelada.')}function confirmAction(title,text,fn){pendingConfirm=fn;$('confirm-title').textContent=title;$('confirm-text').textContent=text;$('confirm-dialog').showModal()}
$('confirm-no').onclick=()=>$('confirm-dialog').close();$('confirm-yes').onclick=()=>{$('confirm-dialog').close();pendingConfirm?.();pendingConfirm=null};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.section').forEach(x=>x.classList.toggle('active',x.id===b.dataset.view));$('title').textContent={operation:'Visão da operação',partners:'Entregadores',history:'Histórico da operação'}[b.dataset.view]});$('new-service').onclick=()=>$('create-dialog').showModal();$('create-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),client=String(f.get('client')).trim(),origin=String(f.get('origin')).trim(),destination=String(f.get('destination')).trim();if(!client||!origin||!destination){toast('Preencha nome, origem e destino.');return}const s={id:'VP-'+state.next++,type:f.get('type'),client,origin,destination,price:Number(f.get('price')),payment:f.get('payment'),status:'Aguardando parceiro',partner:null,events:['Solicitação criada pela central']};state.services.unshift(s);log(s.id+' criado · '+s.type);save();$('create-dialog').close();e.target.reset();toast('Solicitação criada.');detail(s.id)};['search','type-filter','status-filter'].forEach(id=>$(id).addEventListener('input',render));$('services').onclick=e=>{const b=e.target.closest('[data-detail]');if(b)detail(b.dataset.detail)};$('partners-table').onclick=e=>{const b=e.target.closest('[data-partner]');if(!b)return;const p=state.partners.find(x=>x.id===b.dataset.partner);if(!p||busy(p))return;p.online=!p.online;log(p.name+': '+(p.online?'disponível':'offline'));save()};$('reset').onclick=()=>confirmAction('Reiniciar demonstração','As solicitações e alterações feitas neste navegador serão substituídas pelos dados iniciais.',()=>{state=seed();save();toast('Demonstração reiniciada.');});render();
if(document.modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});for(const tool of [{name:'listar_solicitacoes_up',description:'Consultar solicitações fictícias e parceiros da central UP.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({services:state.services,partners:state.partners})},{name:'atribuir_parceiro_up',description:'Atribuir um parceiro disponível a uma solicitação na demonstração local.',inputSchema:{type:'object',properties:{serviceId:{type:'string'},partnerId:{type:'string'}},required:['serviceId','partnerId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.serviceId!=='string'||typeof input.partnerId!=='string')throw Error('Informe os códigos de serviço e parceiro.');return assign(input.serviceId,input.partnerId)}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}}
